def extract_even(data):
    def filter_even(item):
        if isinstance(item, tuple):
            # Recursively process nested tuples
            return tuple(filter_even(sub_item) for sub_item in item if isinstance(sub_item, int) and sub_item % 2 == 0 or isinstance(sub_item, tuple))
        elif isinstance(item, int) and item % 2 == 0:
            # Keep even integers
            return item
        return None

    # Filter out None values from the top-level tuple
    return tuple(filter(lambda x: x is not None, (filter_even(x) for x in data)))

# Example usage and test
assert extract_even((4, 5, (7, 6, (2, 4)), 6, 8)) == (4, (6, (2, 4)), 6, 8)
